import { useState } from 'react';
import { Calendar, Button, ButtonGroup } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange: (date: Date) => void;
  defaultValue?: Date;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

function getQuickOptions(): { label: string; getValue: () => Date }[] {
  const today = startOfDay(new Date());
  return [
    { label: 'Сегодня', getValue: () => today },
    { label: 'Вчера', getValue: () => addDays(today, -1) },
    { label: 'Неделя назад', getValue: () => addDays(today, -7) },
  ];
}

export default function ReportDatePicker({ onChange, defaultValue }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(defaultValue ?? startOfDay(new Date()));

  const handleSelect = (date: Date) => {
    const normalized = startOfDay(date);
    setSelectedDate(normalized);
    onChange(normalized);
  };

  return (
    <div className="jx-stack jx-stack--vertical" style={{ gap: 'var(--jx-space-3)' }}>
      <ButtonGroup className="jx-report-date-picker__quick-options">
        {getQuickOptions().map((option) => (
          <Button
            key={option.label}
            variant="secondary"
            size="sm"
            type="button"
            onClick={() => handleSelect(option.getValue())}
          >
            {option.label}
          </Button>
        ))}
      </ButtonGroup>
      <Calendar
        mode="single"
        numberOfMonths={1}
        selected={selectedDate}
        onSelect={handleSelect}
      />
    </div>
  );
}

